create extension if not exists pgcrypto;
create type public.event_status as enum ('draft','published','finished');
create type public.rsvp_status as enum ('pending','confirmed','declined','partial');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text,created_at timestamptz not null default now());
create table public.templates(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,category text not null,plan text not null,is_published boolean not null default false);
create table public.template_versions(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.templates on delete cascade,version int not null,config jsonb not null default '{}',unique(template_id,version));
create table public.events(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,template_version_id uuid references public.template_versions,slug text unique not null,title text not null,event_type text not null,starts_at timestamptz,ends_at timestamptz,timezone text not null default 'America/Argentina/Buenos_Aires',status public.event_status not null default 'draft',rsvp_deadline timestamptz,content jsonb not null default '{}',created_at timestamptz not null default now());
create table public.event_sections(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,kind text not null,position int not null,enabled boolean not null default true,content jsonb not null default '{}');
create table public.event_venues(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,name text not null,address text,latitude numeric,longitude numeric,instructions text,starts_at timestamptz);
create table public.event_schedule_items(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,title text not null,starts_at timestamptz,position int not null);
create table public.event_media(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,storage_path text not null,kind text not null,position int not null default 0);
create table public.guest_groups(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,name text not null,seats int not null check(seats>0),segment text,phone text,email text,status public.rsvp_status not null default 'pending',confirmed_seats int check(confirmed_seats between 0 and seats),last_activity_at timestamptz);
create table public.guest_members(id uuid primary key default gen_random_uuid(),guest_group_id uuid not null references public.guest_groups on delete cascade,name text not null,attending boolean);
create table public.guest_invitation_tokens(id uuid primary key default gen_random_uuid(),guest_group_id uuid unique not null references public.guest_groups on delete cascade,token_hash text unique not null,expires_at timestamptz,revoked_at timestamptz);
create table public.rsvp_questions(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,key text not null,label text not null,kind text not null,required boolean not null default false,config jsonb not null default '{}',position int not null);
create table public.rsvp_answers(id uuid primary key default gen_random_uuid(),guest_group_id uuid not null references public.guest_groups on delete cascade,question_id uuid references public.rsvp_questions on delete cascade,value jsonb not null,updated_at timestamptz not null default now());
create table public.event_activity(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,actor_group_id uuid references public.guest_groups on delete set null,kind text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.events enable row level security; alter table public.guest_groups enable row level security;
create policy "profile owner" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "event owner" on public.events for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "group event owner" on public.guest_groups for all using(exists(select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid())) with check(exists(select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid()));
